import time
import random

def evaluate_network(net, n):
    target = 1 << n
    for v in range(target):
        bits = [(v >> k) & 1 for k in range(n)]
        for i, j in net:
            if bits[i] > bits[j]:
                bits[i], bits[j] = bits[j], bits[i]
        for k in range(n - 1):
            if bits[k] > bits[k + 1]:
                return False
    return True

def random_search(n, size, budget, start_time):
    while time.time() - start_time < budget:
        net = []
        for _ in range(size):
            i, j = random.randint(0, n-1), random.randint(0, n-1)
            if i != j:
                net.append((min(i,j), max(i,j)))
        if len(net) == size and evaluate_network(net, n):
            return True, time.time() - start_time
    return False, budget

def simulated_annealing(n, size, budget, start_time):
    net = []
    for _ in range(size):
        i, j = random.randint(0, n-1), random.randint(0, n-1)
        if i != j:
            net.append((min(i,j), max(i,j)))
    while len(net) < size:
        net.append((0,1))

    def count_sorted(net, n):
        count = 0
        for v in range(1 << n):
            bits = [(v >> k) & 1 for k in range(n)]
            for i, j in net:
                if bits[i] > bits[j]:
                    bits[i], bits[j] = bits[j], bits[i]
            if all(bits[k] <= bits[k+1] for k in range(n-1)):
                count += 1
        return count

    score = count_sorted(net, n)

    while time.time() - start_time < budget:
        idx = random.randint(0, size-1)
        old = net[idx]
        i, j = random.randint(0, n-1), random.randint(0, n-1)
        if i == j: continue
        net[idx] = (min(i,j), max(i,j))
        new_score = count_sorted(net, n)
        if new_score >= score or random.random() < 0.1:
            score = new_score
            if score == (1 << n): return True, time.time() - start_time
        else:
            net[idx] = old
    return False, budget

def main():
    import json
    n = 7
    size = 16
    budget = 10.0

    start = time.time()
    found_rs, time_rs = random_search(n, size, budget, start)

    start = time.time()
    found_sa, time_sa = simulated_annealing(n, size, budget, start)

    return json.dumps({"random_search": {"found": found_rs, "time": time_rs}, "simulated_annealing": {"found": found_sa, "time": time_sa}})
